//myroom = 0 - Mangle Cove with curtains closed.
//myroom = 1 - Mangle Cove with Mangle peeking from the curtains.
//myroom = 2 - Mangle out of curtain
//myroom = 3 - Mangle in vent
//myroom = 4 - Mangle office vent
//myroom = 5 - On office table
//myroom = 6 - Jumpscare randomly / camera pulled down
myroom = 0
